883  uint8_t Frame::FindPayloadIndex(void) const
   884  {
   885      uint8_t index = SkipSecurityHeaderIndex();
   886  #if OPENTHREAD_CONFIG_MAC_HEADER_IE_SUPPORT
   887      const uint8_t *cur    = NULL;
   888      const uint8_t *footer = GetFooter();
   889  #endif
   890
   891      VerifyOrExit(index != kInvalidIndex);
   892
   893  #if OPENTHREAD_CONFIG_MAC_HEADER_IE_SUPPORT
   894      cur = GetPsdu() + index;
   895
   896      if (IsIePresent())
   897      {
   898          while (cur + sizeof(HeaderIe) <= footer)
   899          {
   900              const HeaderIe *ie  = reinterpret_cast<const HeaderIe *>(cur);
   901              uint8_t         len = static_cast<uint8_t>(ie->GetLength());
   902
   903              cur += sizeof(HeaderIe);
   904              index += sizeof(HeaderIe);
   905
   906              VerifyOrExit(cur + len <= footer, index = kInvalidIndex);
   907
   908              cur += len;
   909              index += len;
   910
   911              if (ie->GetId() == kHeaderIeTermination2)
   912              {
   913                  break;
   914              }
   915          }
   916
